import * as THREE from './vendor/three.module.js';
import {OrbitControls} from './vendor/OrbitControls.js';
import {createModel,categories} from './model.js';
import {product} from './product.js';

const $=id=>document.getElementById(id),stage=$('stage'),host=$('canvasHost');
const state={amount:product.amount,target:product.amount,selected:null,isolated:null,hidden:new Set(),labels:true,xray:false,grid:true,playing:false,rotate:false,view:'perspective',tourTime:0};
let toastTimer;
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2500);}
function icon(name){return `<svg><use href="#i-${name}"/></svg>`;}
const previewSvg='<svg class="preview-svg" viewBox="0 0 200 100"></svg>';
let renderer,scene,camera,controls,model,grid,raycaster,labels=[],selectionBox;
let transitioning=false,cameraTween=null,pointerDown=null,lastFrame=performance.now(),fpsTime=0,frameCount=0;
const pointer=new THREE.Vector2(),tempVec=new THREE.Vector3();
const viewDirections={perspective:new THREE.Vector3(...product.viewDirection).normalize(),front:new THREE.Vector3(0,.02,1),back:new THREE.Vector3(0,.02,-1),top:new THREE.Vector3(.001,1,.001).normalize()};

try{init();}catch(err){console.error(err);$('loading').innerHTML=`<div class="fatal"><h2>3D 视图暂时无法启动</h2><p>请在支持 WebGL 的 Chrome 或 Edge 中打开，<br>并启用浏览器图形加速。</p><button onclick="location.reload()">重新加载</button></div>`;$('renderStatus').textContent='WebGL 初始化失败';}

function init(){
  document.title=product.name+' · 3D 拆解实验室';
  document.querySelector('.stage-heading p').textContent=product.name+' / 交互结构研究';
  document.querySelector('.header-right .mono').textContent='CONCEPT / '+product.code;
  document.querySelector('.inspector-bottom>.mono').textContent=product.code;
  document.querySelector('#infoDialog h2').textContent='探索'+product.name+'的每一层。';
  document.querySelector('#infoDialog p').textContent=product.intro+' 所有模型均为程序化概念结构。';

  renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(host.clientWidth,host.clientHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.3;host.appendChild(renderer.domElement);renderer.domElement.setAttribute('aria-label',product.name+'可交互三维模型');renderer.domElement.tabIndex=0;
  scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(36,host.clientWidth/host.clientHeight,.05,150);camera.position.set(15,10,24);
  controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.065;controls.minDistance=2;controls.maxDistance=60;controls.maxPolarAngle=Math.PI*.94;controls.autoRotateSpeed=.55;controls.addEventListener('start',()=>{cameraTween=null;});
  scene.add(new THREE.HemisphereLight(0xc3ecff,0x25413c,2.2));const key=new THREE.DirectionalLight(0xe7f4ff,3.2);key.position.set(8,12,15);scene.add(key);const rim=new THREE.DirectionalLight(0x96e8bd,2.1);rim.position.set(-8,7,-8);scene.add(rim);const fill=new THREE.DirectionalLight(0xb8c8ff,1.4);fill.position.set(-8,0,9);scene.add(fill);
  const envScene=new THREE.Scene();envScene.add(new THREE.Mesh(new THREE.BoxGeometry(60,60,60),new THREE.MeshBasicMaterial({color:0x425760,side:THREE.BackSide})));for(const [pos,scale,color] of [[[0,18,0],[20,1,12],0xe2eee9],[[16,4,10],[1,18,12],0x9ebcba],[[-14,5,-2],[1,14,16],0x9de4c5]]){const panel=new THREE.Mesh(new THREE.BoxGeometry(...scale),new THREE.MeshBasicMaterial({color}));panel.position.fromArray(pos);envScene.add(panel);}const pmrem=new THREE.PMREMGenerator(renderer);const env=pmrem.fromScene(envScene,.05);scene.environment=env.texture;pmrem.dispose();envScene.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});
  model=createModel();scene.add(model.root);
  grid=new THREE.GridHelper(70,70,0x52776d,0x294a49);grid.position.y=-5.25;grid.material.transparent=true;grid.material.opacity=.14;scene.add(grid);
  const origin=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0,0,-10),new THREE.Vector3(0,0,11)]),new THREE.LineDashedMaterial({color:0x698f80,dashSize:.1,gapSize:.22,transparent:true,opacity:.19}));origin.computeLineDistances();scene.add(origin);grid.userData.origin=origin;
  raycaster=new THREE.Raycaster();selectionBox=new THREE.BoxHelper(new THREE.Object3D(),0xa8f4ca);selectionBox.material.transparent=true;selectionBox.material.opacity=.6;selectionBox.visible=false;scene.add(selectionBox);
  const initialAmount=state.amount;applyPositions(1);grid.position.y=modelBounds().min.y-.7;applyPositions(initialAmount);buildTree();buildLabels();showOverview();bindEvents();updateSlider();fitView('perspective',true);updateVisibility();
  $('partCount').textContent=model.parts.length;$('meshStat').textContent=`${model.parts.length} PARTS / ${String(categories.length).padStart(2,'0')} SYSTEMS`;$('renderStatus').textContent='WEBGL · READY';
  requestAnimationFrame(animate);setTimeout(()=>$('loading').classList.add('done'),250);
  window.__explorer={getState:()=>({amount:state.amount,target:state.target,selected:state.selected,isolated:state.isolated,hidden:[...state.hidden],labels:state.labels,xray:state.xray,grid:state.grid,playing:state.playing,view:state.view,product:product.name,systems:categories.length,parts:model.parts.length,visible:model.parts.filter(p=>p.group.visible).length,renderCalls:renderer.info.render.calls,triangles:renderer.info.render.triangles}),parts:model.parts.map(p=>({id:p.id,name:p.name,cat:p.cat})),select:id=>selectPart(id),project:id=>{const p=model.byId.get(id);const v=p.group.getWorldPosition(new THREE.Vector3()).project(camera);return{x:(v.x+1)*host.clientWidth/2,y:(1-v.y)*host.clientHeight/2,z:v.z}},model};
}

function applyPositions(t){const moduleT=THREE.MathUtils.smoothstep(t,0,.55),detailT=THREE.MathUtils.smoothstep(t,.35,1);for(const p of model.parts)p.group.position.copy(p.home).addScaledVector(p.spread,moduleT).addScaledVector(p.detail,detailT);model.root.updateMatrixWorld(true);}
function setAmount(value,{manual=true}={}){state.target=THREE.MathUtils.clamp(value/100,0,1);if(manual)stopTour();updateSlider();}
function updateSlider(){const v=Math.round(state.target*100);$('explode').value=v;$('explode').style.background=`linear-gradient(90deg,var(--mint) ${v}%,#33484a ${v}%)`;$('explodeValue').innerHTML=`${v}<span>%</span>`;document.querySelectorAll('[data-explode]').forEach(b=>b.classList.toggle('active',v<15?b.dataset.explode==='0':v<65?b.dataset.explode==='48':b.dataset.explode==='100'));$('modeLabel').textContent=v<15?'完整组装':v<65?'模块拆解':'精细拆解';}

function buildTree(){const query=$('search').value.trim().toLowerCase();const open=new Set([...document.querySelectorAll('.category.open')].map(el=>el.dataset.cat));if(!$('partsTree').children.length)open.add(product.openingCategory||categories[0].id);let found=0;const html=categories.map(c=>{const parts=model.parts.filter(p=>p.cat===c.id&&(!query||`${p.name} ${p.en} ${p.id}`.toLowerCase().includes(query)));if(!parts.length)return '';found+=parts.length;return `<section class="category ${open.has(c.id)||query?'open':''}" data-cat="${c.id}"><div class="category-head"><button class="cat-toggle" data-toggle="${c.id}" aria-expanded="${open.has(c.id)||!!query}"><span class="chevron">›</span><span class="category-dot" style="background:${c.color}"></span><span>${c.name}</span><span class="cat-count">${String(parts.length).padStart(2,'0')}</span></button><button class="cat-eye ${state.hidden.has(c.id)?'hidden':''}" data-visible="${c.id}" title="${state.hidden.has(c.id)?'显示':'隐藏'}${c.name}" aria-label="${state.hidden.has(c.id)?'显示':'隐藏'}${c.name}" aria-pressed="${!state.hidden.has(c.id)}">${icon('eye')}</button></div><div class="cat-list">${parts.map(p=>`<button class="part-row ${state.selected===p.id?'active':''}" data-part="${p.id}" title="${p.name}" aria-pressed="${state.selected===p.id}"><span class="part-id">${p.id}</span><span class="part-name">${p.name}</span></button>`).join('')}</div></section>`;}).join('');$('partsTree').innerHTML=html||'<div class="no-results">没有找到匹配零件。<br>试试“镜片”“芯片”或编号。</div>';if(query)$('visibleCount').textContent=`找到 ${found} 个零件`;else updateCount();}
function buildLabels(){labels=categories.map((c,i)=>{const part=model.parts.find(p=>p.cat===c.id&&p.name===c.anchorName)||model.parts.find(p=>p.cat===c.id);if(!part)return null;const el=document.createElement('button');el.className='model-label';el.innerHTML=`<span>${String(i+1).padStart(2,'0')}</span>${c.name}`;el.onclick=()=>selectPart(part.id);$('labels').appendChild(el);return {el,part,cat:c.id,index:i};}).filter(Boolean);}

function updateLabels(){const occupied=[];for(const l of labels){const visible=state.labels&&!state.isolated&&l.part.group.visible&&state.amount>.12;l.el.style.display=visible?'block':'none';if(!visible)continue;tempVec.copy(l.part.group.position).project(camera);let x=(tempVec.x+1)*host.clientWidth/2,y=(1-tempVec.y)*host.clientHeight/2-32;const lift=[-72,-48,17,-85,28,-78,26,20][l.index%8];y+=lift;if(tempVec.z>1||x<60||x>host.clientWidth-58||y<145||y>host.clientHeight-190){l.el.style.display='none';continue;}for(const r of occupied){if(Math.abs(r.x-x)<115&&Math.abs(r.y-y)<32)y-=34;}if(y<142)y=142;l.el.style.left=x+'px';l.el.style.top=y+'px';l.el.classList.toggle('selected',state.selected===l.part.id);occupied.push({x,y});}}

function showOverview(){state.selected=null;selectionBox&&(selectionBox.visible=false);$('inspectorType').textContent='总览';$('inspectorContent').innerHTML=`<div class="preview-card"><span class="preview-number">${product.code} / STRUCTURAL STUDY</span>${previewSvg}<span class="preview-corner">CONCEPT MODEL</span></div><div class="part-english">${product.english} / CONCEPT</div><h3>${product.name}</h3><p class="desc">${product.intro}</p><div class="metric-grid"><div class="metric"><strong>${model.parts.length}</strong><span>可独立探索的零件</span></div><div class="metric"><strong>${String(categories.length).padStart(2,'0')}</strong><span>精密结构系统</span></div></div><div class="section-label">探索路径 / EXPLORE</div><div class="module-tags">${categories.map(c=>`<button data-category-select="${c.id}"><span style="color:${c.color}">●</span> ${c.name}</button>`).join('')}</div><div class="section-label">开始探索 / START HERE</div><p class="desc">拖动下方滑块，让结构徐徐展开。点击模型或左侧零件名称，查看它的功能与装配关系。</p><button id="startExplore" class="primary-btn" style="width:100%;margin-top:15px">${icon('layers')} 开始探索 <span>↗</span></button><p class="inspector-note">所有尺寸、材料与内部排列为概念示意。<br>不对应特定品牌的真实拆机结构。</p>`;document.querySelectorAll('.part-row.active').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});updateMaterials();const assembled=new THREE.Group();for(const p of model.parts){const item=p.group.clone(true);item.position.copy(p.home);assembled.add(item);}renderPartPreview({group:assembled,name:product.name});}
function selectPart(id){const p=model.byId.get(id);if(!p)return;stopTour();if(state.hidden.has(p.cat)){state.hidden.delete(p.cat);buildTree();}if(state.isolated&&state.isolated!==id)state.isolated=id;state.selected=id;updateVisibility();updateMaterials();const c=categories.find(c=>c.id===p.cat);$('inspectorType').textContent='零件';$('inspectorContent').innerHTML=`<div class="preview-card"><span class="preview-number">PART ${p.id} / ${c.en.split(' ')[0]}</span>${previewSvg.replaceAll('#98efc6',c.color)}<span class="preview-corner">${p.cat.toUpperCase()}</span></div><div class="part-english">${p.en}</div><h3>${p.name}</h3><p class="desc">${p.desc}</p><div class="section-label">零件信息 / DETAILS</div><dl><div class="spec-row"><dt>零件编号</dt><dd class="mono">${product.code}-${p.id}</dd></div><div class="spec-row"><dt>所属系统</dt><dd><span style="color:${c.color}">●</span> ${c.name}</dd></div><div class="spec-row"><dt>结构作用</dt><dd>${p.role}</dd></div><div class="spec-row"><dt>材料示意</dt><dd>${p.material}</dd></div><div class="spec-row"><dt>比例参考</dt><dd>${p.size}</dd></div></dl><div class="inspector-actions"><button id="focusPart" class="primary-btn">${icon('focus')} 聚焦零件</button><button id="isolatePart" class="secondary-btn">${icon('cube')} ${state.isolated?'退出隔离':'单独查看'}</button></div><button id="clearSelection" class="secondary-btn" style="width:100%;margin-top:9px">返回整机总览</button><p class="inspector-note">点击“单独查看”可隐藏其他零件，<br>从任意角度观察当前组件。按 Esc 返回。</p>`;$('inspectorContent').scrollTop=0;document.querySelectorAll('.part-row').forEach(b=>{const selected=b.dataset.part===id;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',selected)});const category=document.querySelector(`[data-cat="${p.cat}"]`);category?.classList.add('open');category?.querySelector('.cat-toggle')?.setAttribute('aria-expanded','true');document.querySelector(`[data-part="${id}"]`)?.scrollIntoView({block:'nearest'});renderPartPreview(p);if(state.isolated)focusPart();}
function updateMaterials(){if(!model)return;for(const p of model.parts){const selected=p.id===state.selected;p.group.traverse(o=>{const m=o.material,b=o.userData.base;if(!m||!b)return;const faded=state.xray&&(categories.find(c=>c.id===p.cat)?.xray||p.cat==='shell'||p.cat==='thermal')&&!selected;if(m.emissive){m.emissive.copy(b.emissive||new THREE.Color(0));m.emissiveIntensity=b.emissiveIntensity??1;if(selected){m.emissive.set(0x3fb87c);m.emissiveIntensity=.32;}}if(o.userData.edge){m.color.set(selected?0xb7ffce:0xa7cfc5);m.opacity=selected?.85:b.opacity;}else{m.opacity=faded?.14:b.opacity;m.transparent=faded||b.transparent;m.depthWrite=faded?false:b.depthWrite;}m.needsUpdate=true;});}}
function updateVisibility(){for(const p of model.parts)p.group.visible=!state.hidden.has(p.cat)&&(!state.isolated||p.id===state.isolated);updateCount();if(state.selected&&!model.byId.get(state.selected).group.visible)showOverview();}
function updateCount(){if(!$('search').value)$('visibleCount').textContent=state.isolated?'正在单独查看':state.hidden.size?`${model.parts.filter(p=>p.group.visible).length} / ${model.parts.length} 可见`:'全部可见';}
function clearSelection(){state.isolated=null;updateVisibility();showOverview();fitView(state.view);}
function modelBounds(){const box=new THREE.Box3();for(const p of model.parts)if(p.group.visible)box.expandByObject(p.group);if(box.isEmpty())box.setFromCenterAndSize(new THREE.Vector3(),new THREE.Vector3(6,4,4));return box;}
function moveCamera(position,target,immediate=false){if(immediate){camera.position.copy(position);controls.target.copy(target);controls.update();cameraTween=null;}else cameraTween={from:camera.position.clone(),to:position.clone(),targetFrom:controls.target.clone(),targetTo:target.clone(),start:performance.now(),duration:850};}
function fitView(view='perspective',immediate=false){
  state.view=view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
  const bounds=modelBounds(),target=bounds.getCenter(new THREE.Vector3());target.y+=.12;
  const dir=viewDirections[view],right=new THREE.Vector3(0,1,0).cross(dir).normalize(),up=dir.clone().cross(right).normalize();
  const tangent=Math.tan(THREE.MathUtils.degToRad(camera.fov)/2);let distance=8;
  for(const p of model.parts){if(!p.group.visible)continue;const b=new THREE.Box3().setFromObject(p.group);for(const x of [b.min.x,b.max.x])for(const y of [b.min.y,b.max.y])for(const z of [b.min.z,b.max.z]){const point=new THREE.Vector3(x,y,z).sub(target),depth=point.dot(dir);distance=Math.max(distance,Math.abs(point.dot(right))/(tangent*camera.aspect*.86)+depth,Math.abs(point.dot(up))/(tangent*.55)+depth);}}
  moveCamera(target.clone().addScaledVector(dir,distance+.3),target,immediate);
}
function focusPart(){const p=model.byId.get(state.selected);if(!p)return;const box=new THREE.Box3().setFromObject(p.group),center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3());const dir=camera.position.clone().sub(controls.target).normalize();const distance=Math.max(size.length()*2.1,2.4);moveCamera(center.clone().addScaledVector(dir,distance),center);}
function stopTour(){if(!state.playing)return;state.playing=false;$('playBtn').classList.remove('playing');$('playBtn').setAttribute('aria-pressed','false');$('playIcon').textContent='▶';$('playText').textContent='自动演示';}
function toggleTour(){if(state.playing){stopTour();return;}state.isolated=null;state.hidden.clear();showOverview();updateVisibility();buildTree();state.playing=true;state.tourTime=Math.acos(1-state.amount*2)/Math.PI*7;$('playBtn').classList.add('playing');$('playBtn').setAttribute('aria-pressed','true');$('playIcon').textContent='Ⅱ';$('playText').textContent='暂停演示';const save=state.amount;applyPositions(1);fitView('perspective');applyPositions(save);}
function bindEvents(){
  $('explode').addEventListener('input',e=>setAmount(+e.target.value));$('explode').addEventListener('change',()=>setTimeout(()=>fitView(state.view),450));document.querySelectorAll('[data-explode]').forEach(b=>b.onclick=()=>{setAmount(+b.dataset.explode);if(state.isolated){state.isolated=null;updateVisibility();showOverview();}setTimeout(()=>fitView(state.view),500);});
  $('partsTree').onclick=e=>{const toggle=e.target.closest('[data-toggle]');if(toggle){const node=toggle.closest('.category');node.classList.toggle('open');toggle.setAttribute('aria-expanded',node.classList.contains('open'));return;}const eye=e.target.closest('[data-visible]');if(eye){const c=eye.dataset.visible;state.hidden.has(c)?state.hidden.delete(c):state.hidden.add(c);updateVisibility();buildTree();return;}const row=e.target.closest('[data-part]');if(row)selectPart(row.dataset.part);};
  $('search').addEventListener('input',buildTree);$('collapseAll').onclick=()=>{document.querySelectorAll('.category').forEach(c=>{c.classList.remove('open');c.querySelector('.cat-toggle').setAttribute('aria-expanded','false')});};$('showAll').onclick=()=>{state.hidden.clear();state.isolated=null;$('search').value='';updateVisibility();buildTree();if(state.selected)selectPart(state.selected);fitView(state.view);};
  $('inspectorContent').onclick=e=>{const target=e.target.closest('button');if(!target)return;if(target.dataset.categorySelect){const p=model.parts.find(p=>p.cat===target.dataset.categorySelect);selectPart(p.id);return;}if(target.id==='startExplore'){setAmount(100);selectPart((model.parts.find(p=>p.cat===product.openingCategory)||model.parts[0]).id);}if(target.id==='focusPart')focusPart();if(target.id==='isolatePart'){const id=state.selected;state.isolated=state.isolated?null:id;updateVisibility();selectPart(id);if(!state.isolated)fitView(state.view);}if(target.id==='clearSelection')clearSelection();};
  $('homeBtn').onclick=()=>{state.isolated=null;state.hidden.clear();state.rotate=false;controls.autoRotate=false;$('rotateBtn').classList.remove('active');$('rotateBtn').setAttribute('aria-pressed','false');stopTour();showOverview();updateVisibility();buildTree();fitView('perspective');toast('已重置视角并显示全部零件');};
  $('labelsBtn').onclick=()=>{state.labels=!state.labels;$('labelsBtn').classList.toggle('active',state.labels);$('labelsBtn').setAttribute('aria-pressed',state.labels);};
  $('xrayBtn').onclick=()=>{state.xray=!state.xray;$('xrayBtn').classList.toggle('active',state.xray);$('xrayBtn').setAttribute('aria-pressed',state.xray);updateMaterials();toast(state.xray?'透视已开启：外壳与散热层半透明':'已恢复实体材质');};
  $('gridBtn').onclick=()=>{state.grid=!state.grid;grid.visible=state.grid;grid.userData.origin.visible=state.grid;$('gridBtn').classList.toggle('active',state.grid);$('gridBtn').setAttribute('aria-pressed',state.grid);};
  document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>fitView(b.dataset.view));$('playBtn').onclick=toggleTour;$('rotateBtn').onclick=()=>{state.rotate=!state.rotate;controls.autoRotate=state.rotate;$('rotateBtn').classList.toggle('active',state.rotate);$('rotateBtn').setAttribute('aria-pressed',state.rotate);};
  $('fullscreenBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('当前浏览器不支持页面全屏，请按 F11');}};
  $('captureBtn').onclick=()=>{renderer.render(scene,camera);const out=document.createElement('canvas');out.width=renderer.domElement.width;out.height=renderer.domElement.height;const ctx=out.getContext('2d');ctx.fillStyle='#102024';ctx.fillRect(0,0,out.width,out.height);ctx.drawImage(renderer.domElement,0,0);ctx.fillStyle='#adf2d1';ctx.font=`${Math.round(out.width*.017)}px monospace`;ctx.fillText('EXPLODED / '+product.code,28,38);ctx.font=`${Math.round(out.width*.011)}px monospace`;ctx.fillStyle='#789e95';ctx.fillText('CONCEPT STRUCTURE · XIANGYANG AI OPC',28,out.height-24);out.toBlob(blob=>{if(!blob){toast('导出失败，请重试');return;}const url=URL.createObjectURL(blob);const link=document.createElement('a');link.download=product.code+'-结构视图.png';link.href=url;link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('当前 3D 视图已导出为 PNG');});};
  $('aboutBtn').onclick=$('helpBtn').onclick=()=>$('infoDialog').showModal();$('closeDialog').onclick=()=>$('infoDialog').close();$('infoDialog').onclick=e=>{if(e.target===$('infoDialog')){const r=$('infoDialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('infoDialog').close();}};
  renderer.domElement.addEventListener('pointerdown',e=>{pointerDown={x:e.clientX,y:e.clientY,button:e.button};});renderer.domElement.addEventListener('pointerup',e=>{if(!pointerDown||pointerDown.button!==0)return;const dist=Math.hypot(e.clientX-pointerDown.x,e.clientY-pointerDown.y);pointerDown=null;if(dist<5){const p=pick(e);if(p)selectPart(p.id);else if(state.selected&&!state.isolated)showOverview();}});
  renderer.domElement.addEventListener('pointermove',e=>{if(e.buttons){$('hoverTip').hidden=true;return;}const p=pick(e);renderer.domElement.style.cursor=p?'pointer':'grab';if(p){const r=stage.getBoundingClientRect();$('hoverTip').textContent=`${p.id}  ${p.name}`;$('hoverTip').style.left=Math.min(e.clientX-r.left+15,r.width-220)+'px';$('hoverTip').style.top=e.clientY-r.top+18+'px';$('hoverTip').hidden=false;}else $('hoverTip').hidden=true;});renderer.domElement.addEventListener('pointerleave',()=>$('hoverTip').hidden=true);
  document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){if(e.key==='Escape'){document.activeElement.blur();}return;}if($('infoDialog').open)return;const key=e.key.toLowerCase();if(key===' '){e.preventDefault();toggleTour();}if(key==='r')$('homeBtn').click();if(key==='x')$('xrayBtn').click();if(key==='l')$('labelsBtn').click();if(key==='g')$('gridBtn').click();if(key==='/'){e.preventDefault();$('search').focus();}if(key==='?')$('infoDialog').showModal();if(key==='escape')clearSelection();});
  new ResizeObserver(()=>{camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();renderer.setSize(host.clientWidth,host.clientHeight);}).observe(host);
  renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();$('renderStatus').textContent='图形上下文中断';toast('图形上下文中断，请刷新页面');});
}
function pick(e){const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects(model.parts.filter(p=>p.group.visible).map(p=>p.group),true);for(const hit of hits){if(!hit.object.isMesh)continue;let obj=hit.object;while(obj&&!obj.userData.partId)obj=obj.parent;if(obj)return model.byId.get(obj.userData.partId);}return null;}
function animate(now){requestAnimationFrame(animate);const dt=Math.min((now-lastFrame)/1000,.05);lastFrame=now;if(document.hidden)return;if(state.playing){state.tourTime+=dt;state.target=(1-Math.cos(state.tourTime/7*Math.PI))/2;updateSlider();}const before=state.amount;state.amount=THREE.MathUtils.damp(state.amount,state.target,6,dt);if(Math.abs(state.amount-state.target)<.0001)state.amount=state.target;if(before!==state.amount)applyPositions(state.amount);if(cameraTween){const t=THREE.MathUtils.clamp((now-cameraTween.start)/cameraTween.duration,0,1),ease=1-(1-t)**3;camera.position.lerpVectors(cameraTween.from,cameraTween.to,ease);controls.target.lerpVectors(cameraTween.targetFrom,cameraTween.targetTo,ease);if(t===1)cameraTween=null;}controls.update();if(state.selected){const part=model.byId.get(state.selected);selectionBox.visible=part.group.visible;if(selectionBox.visible)selectionBox.setFromObject(part.group);}else selectionBox.visible=false;updateLabels();renderer.render(scene,camera);frameCount++;fpsTime+=dt;if(fpsTime>1.5){$('renderStatus').textContent=`WEBGL · ${Math.round(frameCount/fpsTime)} FPS · ${model.parts.length} PARTS`;fpsTime=0;frameCount=0;}}

function renderPartPreview(p){
  const mini=new THREE.Scene();mini.environment=scene.environment;
  mini.add(new THREE.HemisphereLight(0xe0f4ff,0x395245,2.3));const light=new THREE.DirectionalLight(0xe9fff1,2.8);light.position.set(3,5,8);mini.add(light);
  const item=p.group.clone(true);item.position.set(0,0,0);mini.add(item);const bounds=new THREE.Box3().setFromObject(item),center=bounds.getCenter(new THREE.Vector3()),size=bounds.getSize(new THREE.Vector3());
  const cam=new THREE.PerspectiveCamera(32,480/260,.01,100);const d=Math.max(size.x/1.65,size.y,size.z)*2.35+.2;cam.position.copy(center).addScaledVector(new THREE.Vector3(.6,.4,1.5).normalize(),d);cam.lookAt(center);
  const target=new THREE.WebGLRenderTarget(480,260);target.texture.colorSpace=THREE.SRGBColorSpace;renderer.setRenderTarget(target);renderer.setClearColor(0x101e22,0);renderer.render(mini,cam);const pixels=new Uint8Array(480*260*4);renderer.readRenderTargetPixels(target,0,0,480,260,pixels);renderer.setRenderTarget(null);renderer.setClearColor(0x000000,0);target.dispose();
  const cv=document.createElement('canvas');cv.width=480;cv.height=260;const ctx=cv.getContext('2d'),img=ctx.createImageData(480,260);for(let y=0;y<260;y++)img.data.set(pixels.subarray((259-y)*480*4,(260-y)*480*4),y*480*4);ctx.putImageData(img,0,0);
  const node=document.createElement('img');node.src=cv.toDataURL();node.alt=p.name+'三维预览';node.className='part-thumbnail';document.querySelector('.preview-card .preview-svg')?.replaceWith(node);
}
